import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Festtags-Card-Editor","description":"Programmation de Noël avec cinq commandes, images de fêtes, décoration GIF et neige.","frontmatter":{"title":"Festtags-Card-Editor","description":"Programmation de Noël avec cinq commandes, images de fêtes, décoration GIF et neige."},"headers":[],"relativePath":"fr/projects/festtags-card-editor/index.md","filePath":"fr/projects/festtags-card-editor/index.md","lastUpdated":1795633237000}'),i={name:"fr/projects/festtags-card-editor/index.md"};function n(o,e,l,d,c,u){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="festtags-card-editor" tabindex="-1">Festtags-Card-Editor <a class="header-anchor" href="#festtags-card-editor" aria-label="Permalink to &quot;Festtags-Card-Editor&quot;">​</a></h1><p><strong>Version 0.1.12</strong> · Éditeur DE/EN · Documentation DE/EN/FR.</p><p><a href="/projects/festtags-card-editor/">Deutsch</a> · <a href="/en/projects/festtags-card-editor/">English</a></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><ul><li>Choix de la région puis du pays : 47 pays et dates personnalisées, traditions occidentales/juliennes.</li><li>Jusqu&#39;à cinq cibles (<code>light</code>, <code>switch</code>, <code>input_boolean</code>) avec des horaires individuels.</li><li>Chaque jour dans une période ou uniquement lors des fêtes choisies ; calcul annuel de l&#39;Avent et passage à l&#39;année suivante automatiques.</li><li>Période par défaut : premier dimanche de l&#39;Avent jusqu&#39;au 10 janvier inclus. Les pauses sont conservées après redémarrage.</li><li>Capteurs pour les fêtes actuelles/suivantes et la prochaine commutation, avec une carte de tableau de bord.</li><li>Icône d&#39;état réelle facultative : <code>mdi:lightbulb</code> allumé, <code>mdi:lightbulb-outline</code> éteint.</li></ul><p>Les listes nationales proposent des fêtes et coutumes, pas un calendrier légal complet. Premier/deuxième jour de Noël, Saint-Étienne, Sinterklaas, Pakjesavond, Trois Rois et Épiphanie sont des entrées séparées. Certaines correspondent à la même date.</p><h2 id="installation-et-mises-a-jour" tabindex="-1">Installation et mises à jour <a class="header-anchor" href="#installation-et-mises-a-jour" aria-label="Permalink to &quot;Installation et mises à jour&quot;">​</a></h2><ol><li>Créer une sauvegarde complète HA et ajouter/actualiser le <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons" target="_blank" rel="noreferrer">dépôt d&#39;applications UGSo</a>.</li><li>Installer/mettre à jour et démarrer <strong>Festtags-Card-Editor</strong>. Architectures : aarch64 et amd64.</li><li><strong>Redémarrer Home Assistant entièrement</strong>, pas seulement l&#39;application, pour charger l&#39;intégration actualisée.</li><li>Ouvrir l&#39;éditeur. À la première installation, choisir <strong>Set up integration</strong>. Régler pays, cibles et horaires, puis enregistrer.</li><li>Cliquer sur <strong>Register card resource</strong>, puis recharger complètement le tableau de bord.</li></ol><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:weihnachtssteuerung-card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Commande de Noël</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Les réglages et images existants sont conservés. La programmation fonctionne dans HA Core même si l&#39;application d&#39;édition est arrêtée. Les administrateurs accèdent à l&#39;éditeur par Ingress. La recherche des entités porte sur le nom, l&#39;identifiant, la zone ou l&#39;appareil. L&#39;interface de l&#39;éditeur existe en allemand et en anglais.</p><h2 id="images-et-arriere-plans-personnels" tabindex="-1">Images et arrière-plans personnels <a class="header-anchor" href="#images-et-arriere-plans-personnels" aria-label="Permalink to &quot;Images et arrière-plans personnels&quot;">​</a></h2><p>Aucune illustration n&#39;est fournie. Utiliser ses propres fichiers avec les droits nécessaires.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Utilisation</th><th>Dossier HA</th><th>Chemin URL</th></tr></thead><tbody><tr><td>Images par pays/fête</td><td><code>/config/www/weihnachtssteuerung/bilder</code></td><td><code>/local/weihnachtssteuerung/bilder</code></td></tr><tr><td>Arrière-plans et décorations</td><td><code>/config/www/weihnachtssteuerung/background</code></td><td><code>/local/weihnachtssteuerung/background</code></td></tr></tbody></table></div><p>Téléverser des fichiers PNG, JPG, WebP ou GIF (maximum 5 Mio/16 mégapixels) ; les animations restent intactes. Les SVG déjà présents peuvent être associés, mais pas téléversés. Les noms en double reçoivent un suffixe sans écrasement. <strong>Unassign</strong>/<strong>No file</strong> supprime uniquement l&#39;association.</p><p>Les images de fêtes ont une hauteur de 110 px dans la carte, avec proportions conservées ; les aperçus de l&#39;éditeur mesurent 90 × 90 px. Plusieurs images peuvent apparaître ensemble. Arrière-plan et décoration ont des réglages indépendants de transparence, taille et position X/Y. Transparence 0 % = visible, 100 % = invisible ; X/Y 0/0 = en haut à gauche, 100/100 = en bas à droite. L&#39;assombrissement améliore la lisibilité. Textes et boutons restent utilisables au-dessus des effets.</p><h2 id="chute-de-neige" tabindex="-1">Chute de neige <a class="header-anchor" href="#chute-de-neige" aria-label="Permalink to &quot;Chute de neige&quot;">​</a></h2><ul><li>Sélectionner <strong>Snowfall</strong> ou <strong>Image + snowfall</strong>. Une décoration GIF séparée peut être activée en plus.</li><li>6 à 40 particules ; diamètre circulaire réel de 1 à 20 pixels CSS, par défaut 4 px.</li><li><strong>Animate snowfall anyway</strong> permet une exception explicite à la réduction des mouvements, uniquement pour cette carte. Désactivée par défaut.</li><li>L&#39;animation continue de se mettre en pause hors écran ou lorsque la page est masquée.</li><li>Enregistrer ; après une mise à jour du fichier de la carte, enregistrer sa ressource et recharger le tableau de bord.</li></ul><h2 id="test-chrome-confirme-le-25-novembre-2026" tabindex="-1">Test Chrome confirmé le 25 novembre 2026 <a class="header-anchor" href="#test-chrome-confirme-le-25-novembre-2026" aria-label="Permalink to &quot;Test Chrome confirmé le 25 novembre 2026&quot;">​</a></h2><p>Sur une installation HA avec la carte <strong>0.1.12</strong>, un GIF chargé et <strong>30 flocons animés simultanément</strong> ont été confirmés. La position des particules a changé entre deux observations ; animation <code>snow-fall</code>, état <code>running</code>. Aucun réglage n&#39;a été modifié pendant ce test combiné. Ce résultat ne garantit pas les performances de toutes les tablettes.</p><p><strong>Firefox anime, mais pas Chrome :</strong> dans le cas observé, Chrome chargeait encore la ressource <strong>0.1.8</strong>. Un rechargement seul n&#39;a pas remplacé l&#39;ancienne référence. Dans l&#39;éditeur actuel, cliquer sur <strong>Register card resource</strong>, puis recharger complètement le tableau de bord. Si la réduction des mouvements est active, enregistrer également l&#39;exception explicite. La carte visible reprend l&#39;animation lorsque le fichier actuel et l&#39;exception sont effectifs.</p><h2 id="liens" tabindex="-1">Liens <a class="header-anchor" href="#liens" aria-label="Permalink to &quot;Liens&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/festtags-card-editor-v0.1.12" target="_blank" rel="noreferrer">Version et téléchargements ZIP</a></li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/festtags_card_editor" target="_blank" rel="noreferrer">Sources et guide détaillé</a></li><li><a href="/fr/projects-mqtt/">UGSo HA Apps</a></li></ul>`,22)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
